def renew_tor_connection():
    """Renew Tor circuit for new IP"""
    with Controller.from_port(port=9051) as controller:
        controller.authenticate()  # Default password often empty
        controller.signal(Signal.NEWNYM)

def get_tor_session():
    """Create session using Tor proxy"""
    session = requests.Session()
    session.proxies = {
        'http': 'socks5://127.0.0.1:9050',
        'https': 'socks5://127.0.0.1:9050'
    }
    return session

@staticmethod
    def clean_system_traces():
        """Clean various system traces"""
        try:
            # Clear command history
            if os.path.exists(os.path.expanduser('~/.bash_history')):
                open(os.path.expanduser('~/.bash_history'), 'w').close()

            # Clear Python history
            if hasattr(sys, 'last_type'):
                delattr(sys, 'last_type')
                delattr(sys, 'last_value')
                delattr(sys, 'last_traceback')
